def f(w):
    r=w[::-1]
    return r[0]+chr(ord(r[1])+1)+chr(ord(r[2])+1)
assert f("SHE")=="EIT" and f("SAD")=="DBT"
r=f("SUN")
opts={"A":"NYT","B":"NTY","C":"NTV","D":"NVT"}
assert r==opts["D"]
assert all(r!=v for k,v in opts.items() if k!="D")

def d(w): return (ord(w[1])-ord(w[0]),ord(w[2])-ord(w[1]))
